/* From Uiverse.io by JaydipPrajapati1910 - Tags: switch, moon, sun, theme-switch, light&dark, sunset, switcher, toggle switch */
.__UIV_SCOPE__ .btn-container {
  display: table-cell;
  vertical-align: middle;
  text-align: center;
}

.__UIV_SCOPE__ .btn-container i {
  display: inline-block;
  position: relative;
  top: -9px;
}

.__UIV_SCOPE__ label {
  font-size: 13px;
  color: #424242;
  font-weight: 500;
}

.__UIV_SCOPE__ .btn-color-mode-switch {
  display: inline-block;
  margin: 0px;
  position: relative;
}

.__UIV_SCOPE__ .btn-color-mode-switch > label.btn-color-mode-switch-inner {
  margin: 0px;
  width: 140px;
  height: 30px;
  background: #E0E0E0;
  border-radius: 26px;
  overflow: hidden;
  position: relative;
  transition: all 0.3s ease;
    /*box-shadow: 0px 0px 8px 0px rgba(17, 17, 17, 0.34) inset;*/
  display: block;
}

.__UIV_SCOPE__ .btn-color-mode-switch > label.btn-color-mode-switch-inner:before {
  content: attr(data-on);
  position: absolute;
  font-size: 12px;
  font-weight: 500;
  top: 7px;
  right: 20px;
}

.__UIV_SCOPE__ .btn-color-mode-switch > label.btn-color-mode-switch-inner:after {
  content: attr(data-off);
  width: 70px;
  height: 16px;
  background: #fff;
  border-radius: 26px;
  position: absolute;
  left: 2px;
  top: 2px;
  text-align: center;
  transition: all 0.3s ease;
  box-shadow: 0px 0px 6px -2px #111;
  padding: 5px 0px;
}

.__UIV_SCOPE__ .btn-color-mode-switch > .alert {
  display: none;
  background: #FF9800;
  border: none;
  color: #fff;
}

.__UIV_SCOPE__ .btn-color-mode-switch input[type="checkbox"] {
  cursor: pointer;
  width: 50px;
  height: 25px;
  opacity: 0;
  position: absolute;
  top: 0;
  z-index: 1;
  margin: 0px;
}

.__UIV_SCOPE__ .btn-color-mode-switch input[type="checkbox"]:checked + label.btn-color-mode-switch-inner {
  background: #151515;
  color: #fff;
}

.__UIV_SCOPE__ .btn-color-mode-switch input[type="checkbox"]:checked + label.btn-color-mode-switch-inner:after {
  content: attr(data-on);
  left: 68px;
  background: #3c3c3c;
}

.__UIV_SCOPE__ .btn-color-mode-switch input[type="checkbox"]:checked + label.btn-color-mode-switch-inner:before {
  content: attr(data-off);
  right: auto;
  left: 20px;
}

.__UIV_SCOPE__ .btn-color-mode-switch input[type="checkbox"]:checked ~ .alert {
  display: block;
}

.__UIV_SCOPE__ .dark-preview {
  background: #0d0d0d;
}

.__UIV_SCOPE__ .white-preview {
  background: #fff;
}
